body:
Hey, maybe you want  the `INDEX(stream; index_expression)` variant?
```shell
$ jq -n --stream 'INDEX(fromstream(1|truncate_stream(inputs)); .id)' test.json
{
  "1": {
    "id": "1",
    "userId": "fa51531d"
  },
  "2": {
    "id": "2",
    "userId": "a167869a"
  }
}
```

Hi, jq development is a bit stalled at the moment, but [fq](https://github.com/wader/fq) can do this already:
```shell
$ cat file.json | fq 'map(from_yaml)'
[
  {
    "apiVersion": "v1",
    "kind": "Namespace",
    "metadata": {
      "name": "test"
    }
  }
]
```

@property
def fieldnames(self):
    if self._fieldnames is None:
        try:
            self._fieldnames = next(self.reader)
        except StopIteration:
            pass
    self.line_num = self.reader.line_num
    return self._fieldnames

@fieldnames.setter
def fieldnames(self, value):
    self._fieldnames = value

def __next__(self):
    if self.line_num == 0:
        # Used only for its side effect.
        self.fieldnames
    row = next(self.reader)
    self.line_num = self.reader.line_num

    # unlike the basic reader, we prefer not to return blanks,
    # because we will typically wind up with a dict full of None
    # values
    while row == []:
        row = next(self.reader)
    d = dict(zip(self.fieldnames, row))
    lf = len(self.fieldnames)
    lr = len(row)
    if lf < lr:
        d[self.restkey] = row[lf:]
    elif lf > lr:
        for key in self.fieldnames[lr:]:
            d[key] = self.restval
    return d

def INDEX(stream; idx_expr):
  reduce stream as $row ({};
    .[$row|idx_expr|
      if type != "string" then tojson
      else .
      end] |= $row);
def INDEX(idx_expr): INDEX(.[]; idx_expr);

